// Fraud Transaction Flagger: core logic (ported from main.py)

// ---- input normaliser (works for Webhook, Form, WhatsApp, Gmail, Sheets and sample data)
const input = $input.all().flatMap(i => {
  const j = i.json || {};
  if (j.messages && Array.isArray(j.messages)) {           // WhatsApp Trigger
    return j.messages.filter(m => m.text).map(m => ({ from: '+' + m.from, text: m.text.body }));
  }
  if (j.Subject !== undefined || j.From !== undefined) {     // Gmail Trigger (simple)
    return [{ from: (j.From || '').replace(/.*<|>.*/g, ''), subject: j.Subject || '', body: j.snippet || j.text || '' }];
  }
  const b = (j.body !== undefined && j.headers !== undefined) ? j.body : j;   // Webhook wraps payload in body
  if (Array.isArray(b)) return b;
  if (b && Array.isArray(b.items)) return b.items;
  return [b];
});

const T = { step_up: 40, block: 70 };
const out = [];
for (const tx of input) {
  const p = tx.profile, reasons = [];
  if (!p) reasons.push([30, 'no history for customer']);
  else {
    const z = (tx.amount - p.mean) / (p.sd || 1);
    if (z > 3) reasons.push([40, `amount is ${z.toFixed(1)} sd above this customer's normal`]);
    else if (z > 2) reasons.push([20, `amount is ${z.toFixed(1)} sd above normal`]);
    if (!p.devices.includes(tx.device)) reasons.push([20, `new device ${tx.device}`]);
    if (!p.beneficiaries.includes(tx.beneficiary)) reasons.push([15, `first transfer to ${tx.beneficiary}`]);
  }
  const h = Number(tx.timestamp.slice(11, 13)); if (h >= 1 && h < 5) reasons.push([15, `unusual hour ${tx.timestamp.slice(11, 16)}`]);
  if ((tx.recent_count_10min || 0) >= 3) reasons.push([25, `${tx.recent_count_10min + 1} transactions in 10 minutes`]);
  const risk = reasons.reduce((s, r) => s + r[0], 0);
  const decision = risk >= T.block ? 'BLOCK' : risk >= T.step_up ? 'STEP-UP' : 'ALLOW';
  out.push({ route: decision, customer: tx.customer, amount: tx.amount, risk, decision, reasons: reasons.map(r => r[1]).join('; ') });
}
return out.map(json => ({ json }));
